# ---------------------------------------------------------------- 4.1 Pricing models
WALK2["clf-pricing-models"] = walk(
    "Buy compute for four very different workloads, then see what data transfer and storage cost.",
    ["On-Demand, Savings Plans and Reserved Instances", "Spot Instances", "Dedicated Hosts, Dedicated Instances, Capacity Reservations",
     "RI flexibility and sharing in AWS Organizations", "Data transfer and storage pricing"],
    [N("web", "Steady web tier", 120, 60, "compute", "24/7 for years"), N("sp", "Savings Plans / RIs", 380, 60, "cost", "1 or 3 yr commit"),
     N("test", "New project", 120, 170, "compute", "unknown usage"), N("od", "On-Demand", 380, 170, "cost", "per second, no commit"),
     N("batch", "Batch jobs", 120, 280, "compute", "can be interrupted"), N("spot", "Spot", 380, 280, "cost", "up to 90% off"),
     N("lic", "Per-socket licence", 120, 390, "compute", "compliance"), N("dh", "Dedicated Host", 380, 390, "cost", "your own server"),
     N("org", "AWS Organizations", 660, 110, "globe", "discounts shared"), N("xfer", "Data transfer", 660, 300, "network", "in free, out paid")],
    [S("problem", "Four workloads", "Four workloads, one budget",
       "A web tier that runs 24/7. A new project with unknown usage. Nightly batch jobs that can be restarted. A database whose licence is tied to physical CPUs.\n\nPaying the same way for all four would waste money.",
       add=["web", "test", "batch", "lic"]),
     S("technique", "On-Demand", "On-Demand: flexible, no commitment",
       "Pay per second or hour with no commitment. It's the best choice for short-term, spiky or unpredictable workloads, like the new project, and the most expensive per hour.",
       add=["od"], edges=[("test", "od")], focus=["od"], learn=[0]),
     S("technique", "Commit", "Savings Plans and RIs: commit and save",
       "Commit to one or three years for up to 72% off. Compute Savings Plans apply across instance families, Regions, Fargate and Lambda. EC2 Instance Savings Plans and Reserved Instances are tied to more specific choices.\n\nPaying All, Partial or No Upfront changes the discount.",
       add=["sp"], edges=[("web", "sp")], focus=["sp"], learn=[0],
       tip="RI flexibility: Regional RIs apply in any AZ and, for Linux, to any size in the same family. Convertible RIs can be exchanged for different attributes."),
     S("technique", "Spot", "Spot: spare capacity, big discount",
       "Spot Instances use spare EC2 capacity at up to 90% off. AWS can take them back with a two-minute warning.\n\nThat's perfect for batch, CI and other fault-tolerant work, and wrong for a database that must not stop.",
       add=["spot"], edges=[("batch", "spot")], focus=["spot"], learn=[1]),
     S("technique", "Dedicated", "Dedicated options and Capacity Reservations",
       "A Dedicated Host is a whole physical server for you, with visibility of sockets and cores for bring-your-own-licence software. Dedicated Instances run on hardware dedicated to you, without host-level control.\n\nOn-Demand Capacity Reservations guarantee capacity in a specific AZ. They give no discount by themselves, but can be combined with Savings Plans.",
       add=["dh"], edges=[("lic", "dh")], focus=["dh"], learn=[2],
       warn="Licence tied to physical cores or sockets? Dedicated Host. Only need single-tenant hardware? Dedicated Instance."),
     S("technique", "Organizations", "Discounts shared across accounts",
       "With consolidated billing in AWS Organizations, RI and Savings Plans discounts apply across all accounts in the organization by default. An unused reservation in one account can cover usage in another. The management account can turn sharing off.",
       add=["org"], edges=[("sp", "org", "shared")], focus=["org"], learn=[3]),
     S("technique", "Transfer + storage", "Data transfer and storage prices",
       "Data into AWS from the internet is free. Data out to the internet is charged per GB. Transfer between Regions is charged, and so is transfer between AZs. Traffic within the same AZ over private IPs is free.\n\nStorage is priced per GB-month by class, plus requests and retrievals. Colder S3 classes store data cheaper but charge to read it.",
       add=["xfer"], focus=["xfer"], learn=[4]),
     S("recap", "Recap", "Match the price model to the workload",
       "Same servers, very different bills.",
       recap=["Unknown or short: On-Demand", "Steady: Savings Plans or Reserved Instances (1 or 3 years)", "Interruptible: Spot (up to 90% off)",
              "Licensing or compliance: Dedicated Host or Dedicated Instance; guaranteed capacity: Capacity Reservation",
              "Discounts are shared in Organizations; inbound data is free, outbound and cross-Region are paid"])])

# ---------------------------------------------------------------- 4.2 Billing tools
WALK2["clf-billing-tools"] = walk(
    "Run the bills for a company with many AWS accounts: one bill, tagged costs, forecasts, alerts and estimates.",
    ["AWS Organizations and consolidated billing", "Cost allocation tags and the Cost and Usage Report", "AWS Cost Explorer", "AWS Budgets",
     "AWS Pricing Calculator, pricing information and billing support"],
    [N("org", "AWS Organizations", 400, 50, "globe", "management account"), N("a1", "Account: Shop", 200, 160, "service"),
     N("a2", "Account: Data", 400, 160, "service"), N("a3", "Account: Dev", 600, 160, "service"),
     N("tags", "Cost allocation tags", 160, 290, "cost", "team=checkout"), N("cur", "Cost and Usage Report", 160, 400, "cost", "every line item"),
     N("ce", "Cost Explorer", 400, 300, "cost", "trends + forecast"), N("bud", "AWS Budgets", 640, 300, "cost", "alerts + actions"),
     N("calc", "Pricing Calculator", 640, 400, "cost", "estimate first")],
    [S("problem", "Who spent it?", "\"Why is the bill 40% higher?\"",
       "The company has many AWS accounts. Finance gets several bills, can't tell which team spent what, and only finds out about overspending at the end of the month.",
       add=["a1", "a2", "a3"]),
     S("technique", "Consolidated", "One bill with AWS Organizations",
       "Put all accounts in AWS Organizations. Consolidated billing gives one bill paid by the management account, still broken down per account.\n\nUsage is combined, so volume pricing tiers and shared RI and Savings Plans discounts benefit everyone.",
       add=["org"], edges=[("a1", "org"), ("a2", "org"), ("a3", "org")], focus=["org"], learn=[0]),
     S("technique", "Tags", "Tag resources by team and project",
       "Cost allocation tags are key-value labels on resources. AWS-generated tags (such as aws:createdBy) and user-defined tags (such as team=checkout) appear in billing only after you activate them in the Billing console.\n\nThe Cost and Usage Report (delivered through Data Exports) gives the most detailed line-item data, including tags.",
       add=["tags", "cur"], edges=[("a1", "tags", "team=checkout"), ("tags", "cur", "line items")], focus=["tags", "cur"], learn=[1]),
     S("technique", "Cost Explorer", "See trends with Cost Explorer",
       "AWS Cost Explorer shows costs over time, grouped by service, account, Region or tag, and forecasts future spend. Here it shows the jump came from the Data account's new cluster.",
       add=["ce"], edges=[("org", "ce", "cost data")], focus=["ce"], learn=[2]),
     S("technique", "Budgets", "Get warned with AWS Budgets",
       "AWS Budgets sets a cost or usage limit and sends alerts, by email or SNS, when actual or forecast spend crosses a threshold. It can also track RI and Savings Plans coverage, and run actions such as applying a restrictive policy.",
       add=["bud"], edges=[("ce", "bud", "thresholds")], focus=["bud"], learn=[3],
       warn="Cost Explorer = analyse past and forecast. Budgets = alert when a threshold is crossed. Pricing Calculator = estimate before you build."),
     S("technique", "Estimate", "Estimate before building",
       "AWS Pricing Calculator estimates the monthly cost of an architecture you haven't built yet. Each service's pricing page and the AWS Price List API give the official prices.\n\nBilling and account questions can go to AWS Support on every plan, including Basic, at no extra cost.",
       add=["calc"], focus=["calc"], learn=[4]),
     S("recap", "Recap", "See it, split it, limit it, plan it",
       "No more month-end surprises.",
       recap=["Organizations: one consolidated bill, shared discounts", "Activate cost allocation tags; detailed data in the Cost and Usage Report",
              "Cost Explorer: trends and forecasts", "Budgets: alerts and actions", "Pricing Calculator for estimates; billing support on all plans"])])

